// === Tab: mySketch ===
const GRAVITY = 0.5,
	FRICTION = 0.95;

var particles = [],
	emmiters = [];

function setup() {
	createCanvas(120, 120);
	background(0);
	pixelDensity(1);

	loadPixels();
	for (let y = 0; y < height; y++) {
		for (let x = 0; x < width; x++) {
			pixels[4 * (y * width + x)] = 0;
			pixels[4 * (y * width + x) + 1] = 0;
			pixels[4 * (y * width + x) + 2] = 0;
			pixels[4 * (y * width + x) + 3] = 255;
		}
	}
	updatePixels();

	for (let i = 0; i < 30; i++) {
		particles.push(new Particle(
			createVector(random(120), random(50)),
			p5.Vector.fromAngle(random(TAU), 5),
		));
	}
}

function draw() {

	for (let p of particles)
		p.update();

	loadPixels();

	for (let y = 0; y < height; y++) {
		for (let x = 0; x < width; x++) {
			let val = 0;

			for (let p of particles) {
				let d = 255-createVector(x, y).dist(p.pos)*20;
				if (d>0)
					val+=d;
			}
			pixels[4 * (y * width + x)] = val*2;
			pixels[4 * (y * width + x) + 1] = val*0.7;
			pixels[4 * (y * width + x) + 2] = val*0.3;
		}
	}

	updatePixels();

}

// === Tab: tab2 ===
class Particle {
	constructor(pos, vel) {
		this.pos = pos;
		this.vel = vel;
	}
	update() {
		if (this.pos.x != constrain(this.pos.x, 0, width) ||
			this.pos.y != constrain(this.pos.y, -50, height)) {
			this.pos.x = random(120);
			this.pos.y = random(-50, -20);
			this.vel = p5.Vector.fromAngle(random(TAU), 5);
		}
		this.vel.y += GRAVITY;
		this.vel.mult(FRICTION);
		this.pos.add(this.vel);
		this.pos.x = round(this.pos.x);
		this.pos.y = round(this.pos.y);
	}
}

// === Tab: tab3 ===
class Emmiter {
	constructor(pos, vel) {
		this.pos = pos;
		this.vel = vel;
	}
	update() {
		this.vel.y += GRAVITY;
		this.vel.mult(FRICTION);
		this.pos.add(this.vel);
		this.pos.x = round(this.pos.x);
		this.pos.y = round(this.pos.y);
	}
}

